{   "name": "r6_method",   "description": "Read the source and location for one R6 class method.",   "inputSchema": {     "type": "object",     "properties": {       "class": {         "type": "string",         "description": "R6 class name."       },       "method": {         "type": "string",         "description": "Method name."       },       "package_root": {         "type": "string",         "description": "Absolute path to the target package root."       }     },     "required": [       "class",       "method"     ],     "additionalProperties": false   } } {   "class": "PackageToolService",   "method": "symbols" } {   "package_root": "/path/to/rairai",   "class": "PackageToolService",   "method": "symbols",   "section": "public",   "signature": "symbols(query = NULL, path = NULL, kind = NULL, exact = TRUE, limit = 50L)",   "source": "symbols = function(
      query = NULL,
      path = NULL,
      kind = NULL,
      exact = TRUE,
      limit = 50L
    ) {
      query <- normalize_optional_string(query, default = NULL)
      path <- normalize_optional_string(path, default = NULL)
      kind <- normalize_optional_string(kind, default = NULL)
      if (identical(str_to_lower(kind %||% ""), "all")) {
        kind <- NULL
      }
      exact <- normalize_logical_value(exact, default = TRUE)
      limit <- normalize_limit_value(limit, default = 50L)

      result <- self$source_index$symbols(
        query = query,
        path = path,
        kind = kind,
        exact = exact,
        limit = limit
      )
      if (has_tool_error(result)) {
        return(tool_error_response(error = result$error))
      }

      response_symbols <- compact_location_records(
        result$symbols,
        include_leading_comment = TRUE,
        source_root = self$root_path
      )
      response <- list(
        query = result$query,
        status = result$status,
        exact = exact,
        filters = result$filters,
        count = length(response_symbols),
        total_count = result$total_count,
        truncated = result$truncated,
        limit = result$limit,
        symbols = response_symbols
      )
      if (!is.null(result$path)) {
        response$path <- result$path
      }
      if (length(result$parse_errors %||% list()) > 0L) {
        response$parse_errors <- result$parse_errors
      }
      if (identical(result$status, "none")) {
        response$next_tools <- private$symbols_no_match_next_tools(
          query = query,
          exact = exact
        )
      }

      tool_value_response(!!!response)
    }",   "location": "R/tool-service.R:108-165" }

